import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';

type ProxyConfig = { host: string; path: string };
type FullConfig = { app: Record<string, unknown>; ssrParameters?: { proxyConfigs?: ProxyConfig[] } };

/**
 * Rewrites an absolute SFCC static asset URL to go through the PWA Kit proxy,
 * avoiding direct browser access to the Demandware host which is typically
 * blocked by Cloudflare WAF outside of the Commerce Cloud network.
 */
export const proxyImageUrl = (url: string): string => {
  try {
    const { hostname, pathname, search } = new URL(url);
    const { ssrParameters } = getConfig() as FullConfig;
    const match = ssrParameters?.proxyConfigs?.find((c) => c.host === hostname);
    if (match) return `/mobify/proxy/${match.path}${pathname}${search}`;
  } catch (_) {
    // relative or malformed URL — return as-is
  }
  return url;
};

